using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Concurrent;
using System.Reflection;

namespace ContosoUniversity.Tests;

/// <summary>
/// Shared test utilities for creating in-memory SchoolContext instances
/// and draining the static notification queue between tests.
/// </summary>
public static class TestHelper
{
    /// <summary>
    /// Creates a fresh in-memory SchoolContext with a unique database name.
    /// </summary>
    public static SchoolContext CreateContext(string dbName = null)
    {
        dbName ??= Guid.NewGuid().ToString();
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName)
            .Options;
        return new SchoolContext(options);
    }

    /// <summary>
    /// Drains the static ConcurrentQueue in NotificationService to prevent cross-test pollution.
    /// </summary>
    public static void DrainNotificationQueue()
    {
        var svc = new NotificationService();
        while (svc.ReceiveNotification() != null) { }
    }

    /// <summary>
    /// Seeds a context with a student and returns it.
    /// </summary>
    public static Student SeedStudent(SchoolContext context, string firstName = "John", string lastName = "Doe", DateTime? enrollmentDate = null)
    {
        var student = new Student
        {
            FirstMidName = firstName,
            LastName = lastName,
            EnrollmentDate = enrollmentDate ?? new DateTime(2020, 9, 1)
        };
        context.Students.Add(student);
        context.SaveChanges();
        return student;
    }

    /// <summary>
    /// Seeds a context with an instructor and returns it.
    /// </summary>
    public static Instructor SeedInstructor(SchoolContext context, string firstName = "Jane", string lastName = "Smith", DateTime? hireDate = null)
    {
        var instructor = new Instructor
        {
            FirstMidName = firstName,
            LastName = lastName,
            HireDate = hireDate ?? new DateTime(2010, 1, 15),
            CourseAssignments = new List<CourseAssignment>()
        };
        context.Instructors.Add(instructor);
        context.SaveChanges();
        return instructor;
    }

    /// <summary>
    /// Seeds a department and returns it.
    /// </summary>
    public static Department SeedDepartment(SchoolContext context, string name = "Engineering", decimal budget = 100000, int? instructorID = null)
    {
        var dept = new Department
        {
            Name = name,
            Budget = budget,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = instructorID
        };
        context.Departments.Add(dept);
        context.SaveChanges();
        return dept;
    }

    /// <summary>
    /// Seeds a course and returns it.
    /// </summary>
    public static Course SeedCourse(SchoolContext context, int courseId, string title, int departmentId, int credits = 3)
    {
        var course = new Course
        {
            CourseID = courseId,
            Title = title,
            Credits = credits,
            DepartmentID = departmentId
        };
        context.Courses.Add(course);
        context.SaveChanges();
        return course;
    }
}

