using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        TestHelper.DrainNotificationQueue();
        _context = TestHelper.CreateContext();
        _controller = new NotificationsController(_context);
    }

    public void Dispose()
    {
        TestHelper.DrainNotificationQueue();
        _controller.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var json = result.Value;
        Assert.NotNull(json);

        // Access dynamic properties
        var type = json.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");

        Assert.True((bool)successProp.GetValue(json));
        Assert.Equal(0, (int)countProp.GetValue(json));
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotificationsInList()
    {
        // Arrange: send notifications via the service
        var svc = new NotificationService();
        svc.SendNotification("Student", "1", EntityOperation.CREATE);
        svc.SendNotification("Course", "2", EntityOperation.UPDATE);

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var json = result.Value;
        var type = json.GetType();
        var successProp = type.GetProperty("success");
        var countProp = type.GetProperty("count");
        var notificationsProp = type.GetProperty("notifications");

        Assert.True((bool)successProp.GetValue(json));
        Assert.Equal(2, (int)countProp.GetValue(json));

        var notifications = notificationsProp.GetValue(json) as List<Notification>;
        Assert.NotNull(notifications);
        Assert.Equal(2, notifications.Count);
        Assert.Equal("Student", notifications[0].EntityType);
        Assert.Equal("Course", notifications[1].EntityType);
    }

    [Fact]
    public void GetNotifications_LimitsToTen()
    {
        // Arrange: send 15 notifications
        var svc = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            svc.SendNotification("Entity", i.ToString(), EntityOperation.CREATE);
        }

        // Act
        var result = _controller.GetNotifications();

        // Assert
        var json = result.Value;
        var type = json.GetType();
        var countProp = type.GetProperty("count");
        Assert.Equal(10, (int)countProp.GetValue(json));
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccess()
    {
        var result = _controller.MarkAsRead(1);

        var json = result.Value;
        var type = json.GetType();
        var successProp = type.GetProperty("success");
        Assert.True((bool)successProp.GetValue(json));
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _controller.Index();
        Assert.IsType<ViewResult>(result);
    }
}

