using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services;

public class NotificationServiceTests : IDisposable
{
    private readonly NotificationService _sut;

    public NotificationServiceTests()
    {
        TestHelper.DrainNotificationQueue();
        _sut = new NotificationService();
    }

    public void Dispose()
    {
        TestHelper.DrainNotificationQueue();
        _sut.Dispose();
    }

    [Fact]
    public void SendNotification_FourParamOverload_EnqueuesNotification()
    {
        // Act
        _sut.SendNotification("Student", "1", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("1", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Student (ID: 1)", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("System", notification.CreatedBy);
        Assert.False(notification.IsRead);
    }

    [Fact]
    public void SendNotification_FiveParamOverload_WithDisplayName_EnqueuesNotification()
    {
        // Act
        _sut.SendNotification("Student", "42", "John Doe", EntityOperation.CREATE, "admin");

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Contains("Student 'John Doe'", notification.Message);
        Assert.Contains("created", notification.Message);
        Assert.Equal("admin", notification.CreatedBy);
    }

    [Fact]
    public void SendNotification_NullUserName_DefaultsToSystem()
    {
        // Act
        _sut.SendNotification("Course", "101", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Equal("System", notification.CreatedBy);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE, "created")]
    [InlineData(EntityOperation.UPDATE, "updated")]
    [InlineData(EntityOperation.DELETE, "deleted")]
    public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
    {
        // Act
        _sut.SendNotification("Department", "5", "Engineering", operation);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains(expectedVerb, notification.Message);
        Assert.Contains("Department 'Engineering'", notification.Message);
        Assert.Equal(operation.ToString(), notification.Operation);
    }

    [Fact]
    public void SendNotification_WithNullDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Student", "99", null, EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 99)", notification.Message);
    }

    [Fact]
    public void SendNotification_WithEmptyDisplayName_UsesIdInMessage()
    {
        // Act
        _sut.SendNotification("Student", "99", "  ", EntityOperation.UPDATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.Contains("Student (ID: 99)", notification.Message);
    }

    [Fact]
    public void ReceiveNotification_EmptyQueue_ReturnsNull()
    {
        // Act
        var result = _sut.ReceiveNotification();

        // Assert
        Assert.Null(result);
    }

    [Fact]
    public void ReceiveNotification_MultipleNotifications_ReturnsFIFO()
    {
        // Arrange
        _sut.SendNotification("A", "1", EntityOperation.CREATE);
        _sut.SendNotification("B", "2", EntityOperation.UPDATE);
        _sut.SendNotification("C", "3", EntityOperation.DELETE);

        // Act & Assert
        var first = _sut.ReceiveNotification();
        Assert.Equal("A", first.EntityType);
        Assert.Equal("1", first.EntityId);

        var second = _sut.ReceiveNotification();
        Assert.Equal("B", second.EntityType);

        var third = _sut.ReceiveNotification();
        Assert.Equal("C", third.EntityType);

        Assert.Null(_sut.ReceiveNotification());
    }

    [Fact]
    public void SendNotification_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.Now.AddSeconds(-2);

        // Act
        _sut.SendNotification("Test", "1", EntityOperation.CREATE);

        // Assert
        var notification = _sut.ReceiveNotification();
        Assert.NotNull(notification);
        Assert.True(notification.CreatedAt >= before);
        Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(2));
    }

    [Fact]
    public void MarkAsRead_DoesNotThrow()
    {
        // Act & Assert (no-op, should not throw)
        var ex = Record.Exception(() => _sut.MarkAsRead(1));
        Assert.Null(ex);
    }

    [Fact]
    public void MarkAsRead_WithAnyId_DoesNotThrow()
    {
        Assert.Null(Record.Exception(() => _sut.MarkAsRead(0)));
        Assert.Null(Record.Exception(() => _sut.MarkAsRead(-1)));
        Assert.Null(Record.Exception(() => _sut.MarkAsRead(int.MaxValue)));
    }

    [Fact]
    public void Dispose_DoesNotThrow()
    {
        var svc = new NotificationService();
        var ex = Record.Exception(() => svc.Dispose());
        Assert.Null(ex);
    }

    [Fact]
    public void SendNotification_QueueCapEnforcement_DoesNotGrowUnbounded()
    {
        // Arrange: enqueue more than max (500)
        for (int i = 0; i < 510; i++)
        {
            _sut.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
        }

        // Act: count remaining
        int count = 0;
        while (_sut.ReceiveNotification() != null) count++;

        // Assert: should be at most 500 (the cap)
        Assert.True(count <= 500, $"Expected at most 500 notifications but got {count}");
        Assert.True(count > 0, "Expected some notifications in the queue");
    }
}

