    [Theory]
    [InlineData(".jpg")]
    [InlineData(".jpeg")]
    [InlineData(".png")]
    [InlineData(".gif")]
    [InlineData(".bmp")]
    public void Create_Post_AllowedExtensions_AreAccepted(string extension)
    {
        var dept = SeedDepartment();
        var course = new Course
        {
            CourseID = 1050 + Math.Abs(extension.GetHashCode()) % 1000,
            Title = "TestCourse",
            Credits = 3,
            DepartmentID = dept.DepartmentID
        };

        var fileMock = new Mock<IFormFile>();
        fileMock.Setup(f => f.FileName).Returns($"test{extension}");
        fileMock.Setup(f => f.Length).Returns(1024);
        fileMock.Setup(f => f.CopyTo(It.IsAny<Stream>()));

        var result = _controller.Create(course, fileMock.Object);

        // Should redirect (success) or not fail due to extension validation
        if (result is ViewResult vr)
        {
            Assert.False(_controller.ModelState.ContainsKey("teachingMaterialImage") &&
                _controller.ModelState["teachingMaterialImage"].Errors.Any(e => e.ErrorMessage.Contains("valid image file")),
                $"Extension {extension} should be allowed");
        }
    }

