        _context.OfficeAssignments.Add(new OfficeAssignment
        {
            InstructorID = instructor.ID,
            Location = "Room 101"
        });
        _context.SaveChanges();

        var oa = _context.OfficeAssignments.Find(instructor.ID);
        Assert.NotNull(oa);
        Assert.Equal("Room 101", oa.Location);
        Assert.Equal(instructor.ID, oa.InstructorID);
    }

