        var course = TestHelper.SeedCourse(_context, 1050, "Chemistry", dept.DepartmentID);
        var instructor = TestHelper.SeedInstructor(_context);

        _context.CourseAssignments.Add(new CourseAssignment
        {
            CourseID = course.CourseID,
            InstructorID = instructor.ID
        });
        _context.SaveChanges();

        var ca = _context.CourseAssignments
            .Include(c => c.Course)
            .Include(c => c.Instructor)
            .First();

        Assert.Equal("Chemistry", ca.Course.Title);
        Assert.Equal(instructor.FirstMidName, ca.Instructor.FirstMidName);
    }

