            .Include(e => e.Course)
            .Include(e => e.Student)
            .First();

        Assert.Equal("Chemistry", enrollment.Course.Title);
        Assert.Equal(student.FirstMidName, enrollment.Student.FirstMidName);
        Assert.Equal(Grade.A, enrollment.Grade);
    }

    [Fact]
    public void Notification_CanBeSavedAndRetrieved()
    {
