        {
            EntityType = "Student",
            EntityId = "1",
            Operation = "CREATE",
            Message = "Test message",
            CreatedAt = DateTime.UtcNow,
            CreatedBy = "System",
            IsRead = false
        };
        _context.Notifications.Add(notification);
        _context.SaveChanges();

        var retrieved = _context.Notifications.First();
        Assert.Equal("Student", retrieved.EntityType);
        Assert.Equal("1", retrieved.EntityId);
        Assert.Equal("CREATE", retrieved.Operation);
        Assert.Equal("Test message", retrieved.Message);
        Assert.False(retrieved.IsRead);
    }

    [Fact]
    public void Department_NullableInstructorID_Works()
    {
        var dept = new Department
        {
            Name = "NoAdmin",
            Budget = 50000,
            StartDate = DateTime.Now,
            InstructorID = null
        };
        _context.Departments.Add(dept);
        _context.SaveChanges();

        var retrieved = _context.Departments.Find(dept.DepartmentID);
        Assert.NotNull(retrieved);
        Assert.Null(retrieved.InstructorID);
    }
}

